"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { MarketplacePageHeader } from "@/components/marketplace/MarketplacePageHeader";
import { JobCard } from "@/components/marketplace/JobCard";
import { MarketplaceEmptyState } from "@/components/marketplace/MarketplaceEmptyState";
import { Pagination } from "@/components/ui/Pagination";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { listJobs, deleteJob } from "@/lib/api/marketplace.api";
import type { Job } from "@/types/marketplace";
import { Briefcase } from "lucide-react";

export default function JobsPage() {
  const router = useRouter();
  const [jobs, setJobs] = useState<Job[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState("");
  const limit = 10;

  useEffect(() => {
    setLoading(true);
    listJobs({ page, limit })
      .then((res) => {
        setJobs(res.data);
        setTotal(res.total);
      })
      .finally(() => setLoading(false));
  }, [page]);

  const filtered = jobs.filter((j) =>
    j.title.toLowerCase().includes(search.toLowerCase()) ||
    (j.company?.toLowerCase().includes(search.toLowerCase()))
  );

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this job?")) return;
    await deleteJob(id);
    setJobs((prev) => prev.filter((j) => j.id !== id));
  };

  return (
    <div>
      <MarketplacePageHeader
        title="Jobs"
        description="Find campus job opportunities"
        createLabel="Post a Job"
        onCreate={() => router.push("/marketplace/jobs/new")}
        showSearch
        searchValue={search}
        onSearchChange={setSearch}
        searchPlaceholder="Search jobs..."
      />
      {loading ? (
        <div className="grid grid-cols-1 gap-4">
          {[...Array(4)].map((_, i) => <LoadingSkeleton key={i} height="h-28" />)}
        </div>
      ) : filtered.length === 0 ? (
        <MarketplaceEmptyState
          icon={<Briefcase className="h-8 w-8" />}
          title="No jobs posted yet"
          description="Be the first to post a job or try a different search."
          actionLabel="Post a Job"
          onAction={() => router.push("/marketplace/jobs/new")}
        />
      ) : (
        <>
          <div className="space-y-3">
            {filtered.map((job) => (
              <div key={job.id} className="relative">
                <JobCard job={job} />
                <button
                  onClick={() => handleDelete(job.id)}
                  className="absolute right-4 top-4 text-xs text-destructive hover:underline"
                >
                  Delete
                </button>
              </div>
            ))}
          </div>
          <Pagination
            currentPage={page}
            totalPages={Math.ceil(total / limit)}
            onPageChange={setPage}
            loading={loading}
          />
        </>
      )}
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import { getListing, updateListing, uploadListingImage } from "@/lib/api/marketplace.api";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { AlertCircle, Upload, X } from "lucide-react";

export default function EditListingPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [price, setPrice] = useState("");
  const [images, setImages] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getListing(id)
      .then((listing) => {
        setTitle(listing.title);
        setDescription(listing.description);
        setPrice(String(listing.price));
        setImages(listing.images || []);
      })
      .catch(() => setError("Failed to load listing"))
      .finally(() => setLoading(false));
  }, [id]);

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const { url } = await uploadListingImage(file);
      setImages((prev) => [...prev, url]);
    } catch {
      setError("Image upload failed");
    } finally {
      setUploading(false);
    }
  };

  const removeImage = (index: number) => {
    setImages((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || !description.trim() || !price) {
      setError("Please fill all required fields.");
      return;
    }
    setSubmitting(true);
    setError(null);
    try {
      await updateListing(id, {
        title: title.trim(),
        description: description.trim(),
        price: Number(price),
        images,
      });
      router.push(`/marketplace/listings/${id}`);
    } catch {
      setError("Failed to update listing.");
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) return <LoadingSkeleton height="h-96" />;

  return (
    <div className="max-w-2xl mx-auto">
      <h1 className="text-2xl font-bold mb-6">Edit Listing</h1>
      <form onSubmit={handleSubmit} className="space-y-6">
        {error && (
          <div className="flex items-center gap-2 rounded-xl bg-destructive/10 p-3 text-destructive text-sm">
            <AlertCircle className="h-4 w-4" />
            {error}
          </div>
        )}
        <Input label="Title" value={title} onChange={(e) => setTitle(e.target.value)} required />
        <div>
          <label className="block text-sm font-medium mb-1.5">Description</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="w-full rounded-lg border border-border bg-background px-4 py-3 text-sm focus:border-primary focus:ring-2 focus:ring-primary/20"
            rows={4}
            required
          />
        </div>
        <Input label="Price (₦)" type="number" value={price} onChange={(e) => setPrice(e.target.value)} required />

        <div>
          <label className="block text-sm font-medium mb-1.5">Images</label>
          <div className="flex flex-wrap gap-3">
            {images.map((url, index) => (
              <div key={index} className="relative h-24 w-24 rounded-lg border border-border overflow-hidden">
                <img src={url} alt="Upload" className="h-full w-full object-cover" />
                <button
                  type="button"
                  onClick={() => removeImage(index)}
                  className="absolute right-1 top-1 rounded-full bg-card p-1 shadow"
                >
                  <X className="h-3 w-3" />
                </button>
              </div>
            ))}
            <label className="flex h-24 w-24 cursor-pointer flex-col items-center justify-center rounded-lg border-2 border-dashed border-border hover:border-primary transition-colors">
              <input type="file" className="hidden" accept="image/*" onChange={handleImageUpload} disabled={uploading} />
              {uploading ? <span className="text-xs text-muted-foreground">Uploading...</span> : <><Upload className="h-5 w-5 text-muted-foreground" /><span className="text-xs text-muted-foreground">Add</span></>}
            </label>
          </div>
        </div>

        <div className="flex gap-3 pt-4">
          <Button type="submit" disabled={submitting} className="flex-1">
            {submitting ? "Saving..." : "Save Changes"}
          </Button>
          <Button type="button" variant="outline" onClick={() => router.back()}>Cancel</Button>
        </div>
      </form>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import { useParams, useRouter } from "next/navigation";
import Link from "next/link";
import { getListing, deleteListing, toggleSaveListing, reportContent } from "@/lib/api/marketplace.api";
import type { Listing } from "@/types/marketplace";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Card } from "@/components/ui/card";
import { LoadingSkeleton } from "@/components/ui/LoadingSkeleton";
import { ArrowLeft, Heart, Share2, AlertTriangle } from "lucide-react";
import { cn } from "@/lib/utils";

export default function ListingDetailPage() {
  const { id } = useParams<{ id: string }>();
  const router = useRouter();
  const [listing, setListing] = useState<Listing | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    getListing(id)
      .then(setListing)
      .catch(() => setError("Failed to load listing"))
      .finally(() => setLoading(false));
  }, [id]);

  const handleDelete = async () => {
    if (!confirm("Are you sure you want to delete this listing?")) return;
    await deleteListing(id);
    router.push("/marketplace/listings");
  };

  const handleSave = async () => {
    if (!listing) return;
    await toggleSaveListing(id);
    setListing({ ...listing, saved: !listing.saved });
  };

  const handleReport = async () => {
    const reason = prompt("Please provide a reason for reporting this listing:");
    if (!reason) return;
    await reportContent({ targetType: "listing", targetId: id, reason });
    alert("Thank you for reporting. We'll review it shortly.");
  };

  if (loading) {
    return (
      <div className="max-w-3xl mx-auto space-y-4">
        <LoadingSkeleton height="h-8" width="w-32" />
        <LoadingSkeleton height="h-96" />
        <LoadingSkeleton height="h-20" />
      </div>
    );
  }

  if (error || !listing) {
    return (
      <div className="max-w-3xl mx-auto text-center py-20">
        <p className="text-destructive">{error || "Listing not found"}</p>
        <Button asChild className="mt-4">
          <Link href="/marketplace/listings">Back to listings</Link>
        </Button>
      </div>
    );
  }

  return (
    <div className="max-w-3xl mx-auto space-y-6">
      {/* Back & actions */}
      <div className="flex items-center justify-between">
        <Button variant="ghost" size="sm" onClick={() => router.back()} className="gap-1">
          <ArrowLeft className="h-4 w-4" />
          Back
        </Button>
        <div className="flex gap-2">
          <Button variant="outline" size="icon-sm" onClick={handleSave} aria-label="Save">
            <Heart className={cn("h-4 w-4", listing.saved && "fill-primary text-primary")} />
          </Button>
          <Button variant="outline" size="icon-sm" aria-label="Share">
            <Share2 className="h-4 w-4" />
          </Button>
        </div>
      </div>

      {/* Main content */}
      <div className="space-y-4">
        {/* Images */}
        <div className="aspect-video w-full overflow-hidden rounded-2xl bg-muted">
          {listing.images?.[0] ? (
            <img src={listing.images[0]} alt={listing.title} className="h-full w-full object-cover" />
          ) : (
            <div className="flex h-full items-center justify-center text-muted-foreground">
              No image
            </div>
          )}
        </div>

        <div className="flex flex-wrap items-start justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold text-foreground">{listing.title}</h1>
            <p className="text-lg font-semibold text-primary">₦{listing.price.toLocaleString()}</p>
          </div>
          <Badge variant={listing.status === "ACTIVE" ? "success" : "default"}>
            {listing.status}
          </Badge>
        </div>

        <Card className="p-5">
          <p className="text-muted-foreground whitespace-pre-wrap">{listing.description}</p>
        </Card>

        <div className="flex flex-wrap gap-3">
          <Button asChild variant="default">
            <Link href={`/marketplace/listings/${id}/edit`}>Edit</Link>
          </Button>
          <Button variant="destructive" onClick={handleDelete}>Delete</Button>
          <Button variant="ghost" onClick={handleReport} className="text-destructive">
            <AlertTriangle className="mr-1 h-4 w-4" />
            Report
          </Button>
        </div>
      </div>
    </div>
  );
}

