// app/study/cgpa/courses/page.tsx
"use client";

import { useEffect, useState } from "react";
import { apiGet, apiPost, apiPatch, apiDelete } from "@/lib/api";
import type { CGPACourse, CGPACourseInput } from "@/types/study";

const emptyCourse: CGPACourseInput = { name: "", code: "", creditHours: 3, grade: "A", semester: "" };

export default function CoursesPage() {
  const [courses, setCourses] = useState<CGPACourse[]>([]);
  const [loading, setLoading] = useState(true);

  // Add/edit state
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState(emptyCourse);
  const [editingId, setEditingId] = useState<string | null>(null);

  const fetchCourses = async () => {
    setLoading(true);
    const data = await apiGet("/cgpa/courses");
    setCourses(data.data || data);
    setLoading(false);
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    const payload = { ...form, creditHours: Number(form.creditHours) };
    if (editingId) {
      await apiPatch(`/cgpa/courses/${editingId}`, payload);
    } else {
      await apiPost("/cgpa/courses", payload);
    }
    setShowForm(false);
    setEditingId(null);
    setForm(emptyCourse);
    fetchCourses();
  };

  const startEdit = (course: CGPACourse) => {
    setForm({
      name: course.name,
      code: course.code,
      creditHours: course.creditHours,
      grade: course.grade,
      semester: course.semester || "",
    });
    setEditingId(course.id);
    setShowForm(true);
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Delete this course?")) return;
    await apiDelete(`/cgpa/courses/${id}`);
    fetchCourses();
  };

  if (loading) return <p>Loading courses...</p>;

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Courses</h1>
        <button
          onClick={() => { setShowForm(true); setEditingId(null); setForm(emptyCourse); }}
          className="bg-primary text-primary-foreground px-4 py-2 rounded"
        >
          Add Course
        </button>
      </div>

      {showForm && (
        <div className="fixed inset-0 bg-black bg-opacity-30 flex items-center justify-center z-50">
          <div className="bg-card rounded p-6 w-full max-w-md">
            <h2 className="text-lg font-semibold mb-4">
              {editingId ? "Edit Course" : "New Course"}
            </h2>
            <form onSubmit={handleSave} className="space-y-4">
              <input
                type="text" placeholder="Course Code" value={form.code}
                onChange={e => setForm({ ...form, code: e.target.value })}
                className="border p-2 w-full" required
              />
              <input
                type="text" placeholder="Course Name" value={form.name}
                onChange={e => setForm({ ...form, name: e.target.value })}
                className="border p-2 w-full" required
              />
              <input
                type="number" min={1} max={6} value={form.creditHours}
                onChange={e => setForm({ ...form, creditHours: Number(e.target.value) })}
                className="border p-2 w-full" required
              />
              <select
                value={form.grade}
                onChange={e => setForm({ ...form, grade: e.target.value })}
                className="border p-2 w-full"
              >
                {["A+", "A", "A-", "B+", "B", "B-", "C+", "C", "C-", "D+", "D", "F"].map(g => (
                  <option key={g} value={g}>{g}</option>
                ))}
              </select>
              <input
                type="text" placeholder="Semester (optional)" value={form.semester}
                onChange={e => setForm({ ...form, semester: e.target.value })}
                className="border p-2 w-full"
              />
              <div className="flex justify-end space-x-2">
                <button type="button" onClick={() => setShowForm(false)} className="px-4 py-2 bg-secondary/50 rounded">
                  Cancel
                </button>
                <button type="submit" className="px-4 py-2 bg-primary text-primary-foreground rounded">
                  {editingId ? "Update" : "Create"}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {courses.length === 0 ? (
        <p className="text-muted-foreground">No courses. Add one to start.</p>
      ) : (
        <div className="bg-card shadow rounded overflow-hidden">
          <table className="w-full">
            <thead className="bg-muted">
              <tr>
                <th className="text-left p-3">Code</th>
                <th className="text-left p-3">Name</th>
                <th className="text-left p-3">Credits</th>
                <th className="text-left p-3">Grade</th>
                <th className="text-right p-3">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {courses.map((c) => (
                <tr key={c.id} className="hover:bg-muted">
                  <td className="p-3">{c.code}</td>
                  <td className="p-3">{c.name}</td>
                  <td className="p-3">{c.creditHours}</td>
                  <td className="p-3 font-medium">{c.grade}</td>
                  <td className="p-3 text-right">
                    <button
                      onClick={() => startEdit(c)}
                      className="text-primary hover:underline mr-3"
                    >
                      Edit
                    </button>
                    <button
                      onClick={() => handleDelete(c.id)}
                      className="text-red-600 hover:underline"
                    >
                      Delete
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

// app/study/materials/upload/page.tsx
"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { apiPost } from "@/lib/api";

export default function UploadMaterialPage() {
  const router = useRouter();
  const [mode, setMode] = useState<"single" | "bulk">("single");
  const [error, setError] = useState<string | null>(null);

  // Single upload state
  const [file, setFile] = useState<File | null>(null);
  const [title, setTitle] = useState("");
  const [courseCode, setCourseCode] = useState("");
  const [courseTitle, setCourseTitle] = useState("");
  const [description, setDescription] = useState("");
  const [visibility, setVisibility] = useState<"PUBLIC" | "PRIVATE" | "LINK_ONLY">("PUBLIC");

  // Bulk upload state
  const [bulkFiles, setBulkFiles] = useState<File[]>([]);
  const [bulkJson, setBulkJson] = useState("");

  const handleSingle = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return setError("File required");
    const formData = new FormData();
    formData.append("file", file);
    formData.append("title", title);
    formData.append("visibility", visibility);
    if (courseCode) formData.append("courseCode", courseCode);
    if (courseTitle) formData.append("courseTitle", courseTitle);
    if (description) formData.append("description", description);
    try {
      await apiPost("/study/materials", formData, true);
      router.push("/study/materials");
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      setError(err.message);
    }
  };

  const handleBulk = async () => {
    if (bulkFiles.length === 0) return setError("Select files");
    let materials;
    try {
      materials = JSON.parse(bulkJson || "[]");
    } catch {
      return setError("Invalid JSON for materials");
    }
    if (!Array.isArray(materials) || materials.length !== bulkFiles.length) {
      return setError("Materials array length must match number of files");
    }
    const formData = new FormData();
    bulkFiles.forEach((f) => formData.append("files", f));
    formData.append("materials", JSON.stringify(materials));
    try {
      await apiPost("/study/materials/bulk", formData, true);
      router.push("/study/materials");
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    } catch (err: any) {
      setError(err.message);
    }
  };

  return (
    <div>
      <h1 className="text-2xl font-bold mb-4">Upload Material</h1>
      <div className="flex space-x-4 mb-6">
        <button
          onClick={() => setMode("single")}
          className={`px-4 py-2 rounded ${mode === "single" ? "bg-primary text-primary-foreground" : "bg-secondary/50"}`}
        >
          Single Upload
        </button>
        <button
          onClick={() => setMode("bulk")}
          className={`px-4 py-2 rounded ${mode === "bulk" ? "bg-primary text-primary-foreground" : "bg-secondary/50"}`}
        >
          Bulk Upload
        </button>
      </div>

      {error && (
        <div className="mb-4 bg-red-100 text-red-700 p-3 rounded">
          {error}
          <button onClick={() => setError(null)} className="ml-2 font-bold">×</button>
        </div>
      )}

      {mode === "single" ? (
        <form onSubmit={handleSingle} className="bg-card shadow rounded p-6 space-y-4 max-w-xl">
          <input type="file" onChange={e => setFile(e.target.files?.[0] || null)} required />
          <input
            type="text" placeholder="Title" value={title} onChange={e => setTitle(e.target.value)}
            className="border p-2 w-full" required
          />
          <input
            type="text" placeholder="Course Code" value={courseCode}
            onChange={e => setCourseCode(e.target.value)} className="border p-2 w-full"
          />
          <input
            type="text" placeholder="Course Title" value={courseTitle}
            onChange={e => setCourseTitle(e.target.value)} className="border p-2 w-full"
          />
          <textarea
            placeholder="Description" value={description}
            onChange={e => setDescription(e.target.value)} className="border p-2 w-full"
          />
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          <select value={visibility} onChange={e => setVisibility(e.target.value as any)} className="border p-2 w-full">
            <option value="PUBLIC">Public</option>
            <option value="PRIVATE">Private</option>
            <option value="LINK_ONLY">Link Only</option>
          </select>
          <button type="submit" className="bg-primary text-primary-foreground px-6 py-2 rounded">
            Upload
          </button>
        </form>
      ) : (
        <div className="bg-card shadow rounded p-6 max-w-xl space-y-4">
          <input type="file" multiple onChange={e => setBulkFiles(Array.from(e.target.files || []))} />
          <textarea
            placeholder='[{"title":"...","visibility":"PUBLIC"}]' value={bulkJson}
            onChange={e => setBulkJson(e.target.value)} className="border p-2 w-full" rows={6}
          />
          <button onClick={handleBulk} className="bg-success text-primary-foreground px-6 py-2 rounded">
            Bulk Upload
          </button>
        </div>
      )}
    </div>
  );
}

