"use client";

import { useEffect, useState } from "react";
import { X, Navigation, MapPin, Accessibility, Loader2 } from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { useMapStore } from "@/lib/map/state/store";
import { mapEntranceService } from "@/lib/map/services";
import { formatLocationType } from "@/lib/map/types/location";
import { getCategoryConfig } from "@/lib/map/config/categories";
import { Entrance } from "@/lib/map/types/entrance";
import type { Location } from "@/lib/map/types/location";

interface LocationPanelProps {
  location: Location | null;
  onNavigate: () => void;
  onClose: () => void;
}

export function LocationPanel({ location, onNavigate, onClose }: LocationPanelProps) {
  const [entrances, setEntrances] = useState<Entrance[]>([]);
  const [loadingEntrances, setLoadingEntrances] = useState(false);
  const { selectedEntrance, setSelectedEntrance } = useMapStore();

  useEffect(() => {
    if (!location) {
      setEntrances([]);
      return;
    }

    const fetchEntrances = async () => {
      setLoadingEntrances(true);
      try {
        const result = await mapEntranceService.getEntrances(location.id, location);
        setEntrances(result);
        // Select the best entrance automatically if not already selected
        if (result.length > 0 && !selectedEntrance) {
          const best = await mapEntranceService.selectBestEntrance(
            location.id,
            location,
            { userLocation: useMapStore.getState().position || undefined }
          );
          if (best) setSelectedEntrance(best);
        }
      } catch (error) {
        console.warn("Failed to fetch entrances", error);
        setEntrances([]);
      } finally {
        setLoadingEntrances(false);
      }
    };

    fetchEntrances();
  }, [location, selectedEntrance, setSelectedEntrance]);

  if (!location) return null;

  const category = getCategoryConfig(location.type);

  return (
    <Card className="h-full rounded-none md:rounded-lg shadow-lg border-t md:border-t-0 md:border-l border-border overflow-hidden flex flex-col">
      <div className="flex items-center justify-between p-4 border-b">
        <h2 className="text-lg font-semibold truncate">{location.name}</h2>
        <Button variant="ghost" size="icon" onClick={onClose} aria-label="Close panel">
          <X className="w-5 h-5" />
        </Button>
      </div>

      <CardContent className="flex-1 overflow-y-auto p-4 space-y-4">
        {/* Type badge */}
        <div className="flex items-center gap-2">
          <Badge
            style={{ backgroundColor: category.hexColor }}
            className="text-white border-0"
          >
            {formatLocationType(location.type)}
          </Badge>
          {location.distanceM != null && (
            <span className="text-sm text-muted-foreground">
              {location.distanceM < 1000
                ? `${Math.round(location.distanceM)} m`
                : `${(location.distanceM / 1000).toFixed(1)} km`}
            </span>
          )}
        </div>

        {/* Description */}
        {location.description && (
          <p className="text-sm text-muted-foreground whitespace-pre-wrap">
            {location.description}
          </p>
        )}

        {/* Image */}
        {location.imageUrl && (
          <div className="relative aspect-video w-full overflow-hidden rounded-md">
            <img
              src={location.imageUrl}
              alt={location.name}
              className="object-cover w-full h-full"
              onError={(e) => {
                (e.target as HTMLImageElement).style.display = "none";
              }}
            />
          </div>
        )}

        {/* Entrances */}
        <div>
          <h3 className="text-sm font-medium mb-2">Entrances</h3>
          {loadingEntrances ? (
            <div className="flex items-center gap-2 text-sm text-muted-foreground">
              <Loader2 className="w-4 h-4 animate-spin" />
              Loading entrances...
            </div>
          ) : entrances.length > 0 ? (
            <ul className="space-y-1.5">
              {entrances.map((entrance) => (
                <li
                  key={entrance.id}
                  className={`flex items-center gap-2 text-sm p-2 rounded-md cursor-pointer hover:bg-muted/50 transition-colors ${
                    selectedEntrance?.id === entrance.id ? "bg-muted" : ""
                  }`}
                  onClick={() => setSelectedEntrance(entrance)}
                >
                  <MapPin className="w-4 h-4 text-muted-foreground shrink-0" />
                  <span className="flex-1 truncate">{entrance.name}</span>
                  {entrance.isAccessible && (
                    <Accessibility className="w-4 h-4 text-blue-500" />
                  )}
                </li>
              ))}
            </ul>
          ) : (
            <p className="text-sm text-muted-foreground">No entrance information available.</p>
          )}
        </div>

        {/* Metadata */}
{location.metadata && Object.keys(location.metadata).length > 0 && (
  <div className="text-sm space-y-1">
    <h3 className="font-medium">Additional Info</h3>
    {typeof location.metadata.openingHours === 'string' && (
      <p>
        <span className="text-muted-foreground">Hours: </span>
        {location.metadata.openingHours}
      </p>
    )}
    {typeof location.metadata.capacity === 'number' && (
      <p>
        <span className="text-muted-foreground">Capacity: </span>
        {location.metadata.capacity}
      </p>
    )}
  </div>
)}
      </CardContent>

      {/* Action buttons */}
      <div className="p-4 border-t flex gap-2">
        <Button className="flex-1" onClick={onNavigate}>
          <Navigation className="w-4 h-4 mr-2" />
          Navigate
        </Button>
        <Button variant="outline" onClick={onClose}>
          Close
        </Button>
      </div>
    </Card>
  );
}

import React from "react";
"use client";

// eslint-disable-next-line @typescript-eslint/no-unused-vars
import { useEffect, useRef, useCallback } from "react";
// eslint-disable-next-line @typescript-eslint/no-unused-vars
import maplibregl, { LngLatLike, GeoJSONSource } from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { useMapStore } from "@/lib/map/state/store";
import { mapConfigService } from "@/lib/map/services";
import { isMapLocation } from "@/lib/map/utils";
import { LayerManager } from "@/lib/map/utils";
import { Loader2 } from "lucide-react";

interface MapCanvasProps {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  locations: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  selectedLocation: any | null;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  onSelectLocation: (location: any) => void;
  userLocation?: { lat: number; lng: number };
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  currentRoute?: any;
}

export default function MapCanvas({
  locations,
  selectedLocation,
  onSelectLocation,
  userLocation,
  currentRoute,
}: MapCanvasProps) {
  const mapContainer = useRef<HTMLDivElement>(null);
  const map = useRef<maplibregl.Map | null>(null);
  const layerManagerRef = useRef<LayerManager | null>(null);
  const [mapTilerKey, setMapTilerKey] = React.useState<string | undefined>(undefined);
  const [mapReady, setMapReady] = React.useState(false);
  const { camera } = useMapStore();

  // Fetch API key
  useEffect(() => {
    mapConfigService
      .getMapConfig()
      .then((cfg) => setMapTilerKey(cfg.maptilerApiKey ?? undefined))
      .catch(() => setMapTilerKey(""));
  }, []);

  // Init map
  useEffect(() => {
    if (map.current || !mapContainer.current || mapTilerKey === undefined) return;
    let cancelled = false;

    (async () => {
      const maplibre = await import("maplibre-gl");
      const maplibregl = maplibre.default ?? maplibre;
      if (cancelled || !mapContainer.current) return;

      const style = mapTilerKey
        ? `https://api.maptiler.com/maps/hybrid/style.json?key=${mapTilerKey}`
        : {
            version: 8 as const,
            sources: {
              osm: {
                type: "raster" as const,
                tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
                tileSize: 256,
                attribution: "© OpenStreetMap contributors",
              },
            },
            layers: [{ id: "osm", type: "raster" as const, source: "osm" }],
          };

      const mapInstance = new maplibregl.Map({
        container: mapContainer.current,
        style,
        center: [camera.center[0], camera.center[1]] as LngLatLike,
        zoom: camera.zoom,
        pitch: camera.pitch,
        bearing: camera.bearing,
        antialias: true,
      });

      mapInstance.addControl(new maplibregl.NavigationControl({ visualizePitch: true }), "top-right");

      mapInstance.on("load", () => {
        if (cancelled) return;
        setMapReady(true);
        const lm = new LayerManager(mapInstance);
        layerManagerRef.current = lm;

        // Add sources and layers
        lm.addSource({
          id: "locations",
          type: "geojson",
          data: { type: "FeatureCollection", features: [] },
        });
        lm.addLayer({
          id: "locations",
          type: "circle",
          source: "locations",
          paint: {
            "circle-color": ["get", "color"],
            "circle-radius": ["case", ["boolean", ["feature-state", "selected"], false], 10, 7],
            "circle-opacity": 0.8,
            "circle-stroke-width": 2,
            "circle-stroke-color": ["case", ["boolean", ["feature-state", "selected"], false], "#1e40af", "#fff"],
          },
        });
        lm.addLayer({
          id: "locations-labels",
          type: "symbol",
          source: "locations",
          layout: {
            "text-field": ["get", "name"],
            "text-font": ["Open Sans Regular"],
            "text-size": 12,
            "text-offset": [0, 1.5],
            "text-anchor": "top",
            "text-allow-overlap": false,
          },
          paint: {
            "text-color": "#000",
            "text-halo-color": "#fff",
            "text-halo-width": 1,
          },
        });

        mapInstance.on("click", "locations", (e) => {
          if (!e.features || e.features.length === 0) return;
          const locationId = e.features[0].properties?.id;
          const location = locations.find((loc) => loc.id === locationId);
          if (location) onSelectLocation(location);
        });

        mapInstance.on("mouseenter", "locations", () => {
          if (mapInstance) mapInstance.getCanvas().style.cursor = "pointer";
        });
        mapInstance.on("mouseleave", "locations", () => {
          if (mapInstance) mapInstance.getCanvas().style.cursor = "";
        });

        // Add route source
        lm.addSource({
          id: "route",
          type: "geojson",
          data: { type: "FeatureCollection", features: [] },
        });
        lm.addLayer({
          id: "route-line",
          type: "line",
          source: "route",
          paint: {
            "line-color": "#3b82f6",
            "line-width": 4,
            "line-opacity": 0.8,
          },
        });
        // user location
        lm.addSource({
          id: "user-location",
          type: "geojson",
          data: { type: "FeatureCollection", features: [] },
        });
        lm.addLayer({
          id: "user-location",
          type: "circle",
          source: "user-location",
          paint: {
            "circle-color": "#fff",
            "circle-radius": 6,
            "circle-stroke-width": 2,
            "circle-stroke-color": "#3b82f6",
          },
        });
      });

      map.current = mapInstance;
    })();

    return () => {
      cancelled = true;
      if (map.current) {
        map.current.remove();
        map.current = null;
        layerManagerRef.current = null;
      }
    };
  }, [mapTilerKey]);

  // Update locations
  useEffect(() => {
    if (!mapReady || !layerManagerRef.current) return;
    const features = locations
      .filter(isMapLocation)
      .map((loc) => ({
        type: "Feature" as const,
        geometry: { type: "Point" as const, coordinates: [loc.longitude, loc.latitude] },
        properties: {
          id: loc.id,
          name: loc.name,
          type: loc.type,
          color: getLocationColor(loc.type),
        },
      }));
    layerManagerRef.current.updateSourceData("locations", {
      type: "FeatureCollection",
      features,
    });
  }, [locations, mapReady]);

  // Update selection state
  useEffect(() => {
    if (!mapReady || !layerManagerRef.current) return;
    // Clear previous
    locations.forEach((loc) => {
      if (map.current) {
        map.current.setFeatureState(
          { source: "locations", id: loc.id },
          { selected: false }
        );
      }
    });
    if (selectedLocation && isMapLocation(selectedLocation)) {
      if (map.current) {
        map.current.setFeatureState(
          { source: "locations", id: selectedLocation.id },
          { selected: true }
        );
      }
    }
  }, [selectedLocation, locations, mapReady]);

  // Update user location
  useEffect(() => {
    if (!mapReady || !layerManagerRef.current || !userLocation) return;
    layerManagerRef.current.updateSourceData("user-location", {
      type: "FeatureCollection",
      features: [
        {
          type: "Feature",
          geometry: { type: "Point", coordinates: [userLocation.lng, userLocation.lat] },
          properties: {},
        },
      ],
    });
  }, [userLocation, mapReady]);

  // Update route
  useEffect(() => {
    if (!mapReady || !layerManagerRef.current) return;
    if (!currentRoute) {
      layerManagerRef.current.updateSourceData("route", { type: "FeatureCollection", features: [] });
      return;
    }
    const features = [];
    if (currentRoute.geometry) {
      features.push({
        type: "Feature",
        geometry: currentRoute.geometry,
        properties: { type: "line" },
      });
    }
    if (currentRoute.waypoints) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      currentRoute.waypoints.forEach((wp: any, idx: number) => {
        features.push({
          type: "Feature",
          geometry: { type: "Point", coordinates: [wp.lng, wp.lat] },
          properties: { index: idx },
        });
      });
    }
    layerManagerRef.current.updateSourceData("route", {
      type: "FeatureCollection",
      features,
    });
  }, [currentRoute, mapReady]);

  return (
    <div className="relative w-full h-full">
      <style>{`@import url("https://unpkg.com/maplibre-gl@4.7.1/dist/maplibre-gl.css");`}</style>
      {mapTilerKey === undefined ? (
        <div className="w-full h-full flex items-center justify-center bg-muted">
          <Loader2 className="w-6 h-6 animate-spin text-primary" />
        </div>
      ) : (
        <div ref={mapContainer} className="w-full h-full" />
      )}
    </div>
  );
}

function getLocationColor(type: string): string {
  const colors: Record<string, string> = {
    BUILDING: "#ef4444",
    CLASSROOM: "#f97316",
    LIBRARY: "#eab308",
    CAFETERIA: "#22c55e",
    LAB: "#06b6d4",
    GYM: "#8b5cf6",
    PARKING: "#ec4899",
    ENTRANCE: "#3b82f6",
    RESTROOM: "#14b8a6",
  };
  return colors[type] || "#6b7280";
}

